import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';

import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';

import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';
import { AuthStateService } from 'src/app/shared/services/auth-state.service';

@Component({
  selector: 'app-all-companies',
  templateUrl: './all-companies.component.html',
  styleUrls: ['./all-companies.component.css']
})
export class AllCompaniesComponent implements OnInit {
  jobs: Job[] = [];
  companies: Company[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';

  constructor(
    private readonly router: Router,
    private readonly jobService: JobService,
    private readonly compService: CompanyService,
    private readonly jobSeekerService: JobseekerService,
    private readonly authState: AuthStateService
  ) {}

  ngOnInit(): void {
    this.isLoggedIn = this.authState.isLoggedIn;
    this.profileRoute = this.authState.profileRoute;
    const id = this.authState.id;

    if (this.isLoggedIn && id !== null) {
      if (this.authState.role === 'COMPANY') {
        this.compService.getCompanyById(id).subscribe((company: Company) => {
          this.initials = this.authState.initialsFromCompany(company);
        });
      } else {
        this.jobSeekerService.getJobSeekerById(id).subscribe((user) => {
          this.initials = this.authState.initialsFromSeeker(user);
        });
      }
    }

    this.loadAllJobs();
    this.loadAllCompanies();
  }

  loadAllJobs(): void {
    this.jobService.getAllJobs().subscribe((res) => {
      this.jobs = res;
    });
  }

  loadAllCompanies(): void {
    this.compService.getAllCompanies().subscribe((res) => {
      this.companies = res;
    });
  }

  signup(): void {
    this.router.navigate(['/register']);
  }

  login(): void {
    this.router.navigate(['/login']);
  }

  logout(): void {
    this.authState.logout();
  }

  goToProfile(): void {
    this.profileRoute = this.authState.profileRoute;
  }
}
